  "createSchedule": {
    "parameters": {},
    "body": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 120,
          "description": "Display name shown in the dashboard."
        },
        "sourceType": {
          "type": "string",
          "enum": [
            "cron"
          ],
          "description": "Always cron for schedules."
        },
        "sourceConfig": {
          "type": "object",
          "properties": {
            "cron": {
              "type": "object",
              "properties": {
                "frequency": {
                  "type": "string",
                  "enum": [
                    "daily",
                    "weekly",
                    "monthly",
                    "custom"
                  ],
                  "description": "How often the schedule runs."
                },
                "hour": {
                  "type": "integer",
                  "minimum": 0,
                  "maximum": 23,
                  "description": "Hour of the day to run, in UTC (0-23)."
                },
                "minute": {
                  "type": "integer",
                  "minimum": 0,
                  "maximum": 59,
                  "description": "Minute of the hour to run (0-59)."
                },
                "dayOfWeek": {
                  "type": "integer",
                  "minimum": 0,
                  "maximum": 6,
                  "description": "Day of the week for weekly schedules, 0 (Sunday) to 6 (Saturday). Required when frequency is weekly."
                },
                "dayOfMonth": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 31,
                  "description": "Day of the month for monthly schedules (1-31). Required when frequency is monthly."
                },
                "intervalDays": {
                  "type": "integer",
                  "minimum": 2,
                  "maximum": 90,
                  "description": "Run every N days (2-90). Required when frequency is custom."
                },
                "anchorDate": {
                  "type": "string",
                  "pattern": "^\\d{4}-\\d{2}-\\d{2}$",
                  "description": "UTC calendar date (YYYY-MM-DD) a custom interval counts from. Defaults to today."
                }
              },
              "required": [
                "frequency",
                "hour",
                "minute"
              ]
            }
          },
          "required": [
            "cron"
          ]
        },
        "targets": {
          "type": "object",
          "properties": {
            "repositoryIds": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "minItems": 1,
              "description": "GitHub integration IDs to generate from, as returned by GET /v1/integrations."
            }
          },
          "required": [
            "repositoryIds"
          ]
        },
        "outputType": {
          "type": "string",
          "enum": [
            "changelog",
            "blog_post",
            "linkedin_post",
            "twitter_post",
            "image"
          ],
          "description": "Type of content each run generates."
        },
        "outputConfig": {
          "type": "object",
          "properties": {
            "publishDestination": {
              "type": "string",
              "enum": [
                "webflow",
                "framer",
                "custom"
              ],
              "description": "Where auto-published posts are sent."
            },
            "brandVoiceId": {
              "type": "string",
              "minLength": 1,
              "description": "Brand identity ID to write in. Defaults to the organization's default brand identity."
            },
            "instructions": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Free-text brief for this schedule, passed to the writer on every run on top of the brand's custom instructions. Use it to steer the angle of the content, for example tutorial-style blog posts."
            }
          }
        },
        "enabled": {
          "type": "boolean",
          "description": "Whether the schedule runs. Disabled schedules are stored but never fire."
        },
        "autoPublish": {
          "type": "boolean",
          "default": false,
          "description": "Publish generated posts automatically instead of saving them as drafts."
        },
        "lookbackWindow": {
          "type": "string",
          "enum": [
            "current_day",
            "yesterday",
            "last_7_days",
            "last_14_days",
            "last_30_days"
          ],
          "default": "last_7_days",
          "description": "How far back each run collects source activity."
        }
      },
      "required": [
        "name",
        "sourceType",
        "sourceConfig",
        "targets",
        "outputType",
        "enabled"
      ]
    }
  },
