  "schedulePost": {
    "parameters": {
      "postId": {
        "type": "string",
        "minLength": 1,
        "pattern": "^[A-Za-z0-9_-]{1,100}$"
      }
    },
    "body": {
      "type": "object",
      "properties": {
        "scheduledAt": {
          "type": "string",
          "format": "date-time",
          "description": "When to publish, as an ISO 8601 timestamp. At most one year ahead; a time up to five minutes in the past publishes right away."
        },
        "timeZone": {
          "type": "string",
          "minLength": 1,
          "maxLength": 100,
          "default": "UTC",
          "description": "IANA time zone the schedule was picked in. Used for display and emails only."
        },
        "destinations": {
          "type": "array",
          "items": {
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "destination": {
                    "type": "string",
                    "enum": [
                      "github"
                    ]
                  },
                  "repositoryId": {
                    "type": "string",
                    "minLength": 1,
                    "pattern": "^[A-Za-z0-9_-]{1,100}$",
                    "description": "GitHub integration ID from GET /v1/integrations. Only for blog posts and changelogs."
                  },
                  "merge": {
                    "type": "boolean",
                    "default": true,
                    "description": "Merge the pull request at the scheduled time. When false, the pull request is only opened or updated."
                  }
                },
                "required": [
                  "destination",
                  "repositoryId"
                ]
              },
              {
                "type": "object",
                "properties": {
                  "destination": {
                    "type": "string",
                    "enum": [
                      "social"
                    ]
                  },
                  "accountId": {
                    "type": "string",
                    "minLength": 1,
                    "pattern": "^[A-Za-z0-9_-]{1,100}$",
                    "description": "Connected X or LinkedIn account ID. Only for tweets and LinkedIn posts, on an account of the matching platform."
                  }
                },
                "required": [
                  "destination",
                  "accountId"
                ]
              }
            ]
          },
          "maxItems": 2,
          "default": [],
          "description": "Where the post goes out besides Notra. The post is always marked as published in Notra at the scheduled time."
        }
      },
      "required": [
        "scheduledAt"
      ]
    }
  },
